-- Safe SarkariJobAlert schema/migration. Does not delete existing rows.
create table if not exists public.jobs (id bigint generated by default as identity primary key,title text not null,department text,category text not null default 'Latest Jobs',vacancies text,notification_date date,last_date date,dob_from date,dob_to date,qualification text,fees text,age_limit text,selection_process text,notification_url text,apply_url text,source_url text,description text,status text not null default 'draft' check(status in ('draft','published')),created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.jobs add column if not exists notification_date date;
alter table public.jobs add column if not exists dob_from date;
alter table public.jobs add column if not exists dob_to date;
alter table public.jobs add column if not exists source_url text;
alter table public.jobs add column if not exists updated_at timestamptz not null default now();
alter table public.jobs add column if not exists created_by uuid;
alter table public.jobs enable row level security;
drop policy if exists "Public can read published jobs" on public.jobs;
create policy "Public can read published jobs" on public.jobs for select to anon,authenticated using(status='published');
drop policy if exists "Authenticated users manage jobs" on public.jobs;
create policy "Authenticated users manage jobs" on public.jobs for all to authenticated using(auth.uid() is not null) with check(auth.uid() is not null);
create table if not exists public.push_subscriptions(id bigint generated by default as identity primary key,token text not null unique,user_agent text,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.push_subscriptions enable row level security;
drop policy if exists "Visitors can subscribe to push" on public.push_subscriptions;
create policy "Visitors can subscribe to push" on public.push_subscriptions for insert to anon,authenticated with check(length(token)>20);
drop policy if exists "Visitors can refresh their push token" on public.push_subscriptions;
create policy "Visitors can refresh their push token" on public.push_subscriptions for update to anon,authenticated using(false) with check(false);
